create type public.journal_status as enum ('draft','posted','reversed');
create table public.journal_entries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),branch_id uuid references public.branches(id),financial_year_id uuid references public.financial_years(id),journal_number text, journal_date date not null,source_type text not null check(source_type in ('manual_journal','opening_balance','sales_invoice','sales_credit_note','purchase_bill','purchase_debit_note','customer_receipt','supplier_payment','expense','bank_transfer','cash_receipt','cash_payment')),source_id uuid,reference text,description text not null default '',status public.journal_status not null default 'draft',reversal_of_journal_id uuid references public.journal_entries(id),reversed_by_journal_id uuid references public.journal_entries(id),posted_at timestamptz,posted_by uuid references auth.users(id),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,journal_number),unique nulls not distinct(organization_id,source_type,source_id));
create table public.journal_lines(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),journal_entry_id uuid not null references public.journal_entries(id) on delete cascade,line_number smallint not null,account_id uuid not null references public.accounts(id),description text,debit_amount numeric(20,6) not null default 0 check(debit_amount>=0),credit_amount numeric(20,6) not null default 0 check(credit_amount>=0),currency_code text not null default 'AED' check(currency_code='AED'),tax_rate_id uuid references public.tax_rates(id),tax_amount numeric(20,6),party_type text,party_id uuid,branch_id uuid references public.branches(id),created_at timestamptz not null default now(),unique(journal_entry_id,line_number),check((debit_amount=0) <> (credit_amount=0)));
alter table public.opening_balance_batches add column posted_journal_id uuid references public.journal_entries(id);
create index journal_entries_org_date_idx on public.journal_entries(organization_id,journal_date,status); create index journal_lines_org_account_idx on public.journal_lines(organization_id,account_id); create index journal_lines_journal_idx on public.journal_lines(journal_entry_id);
create or replace function public.assert_journal_draft(p_organization_id uuid,p_journal_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,public as $$ begin perform public.assert_accounting_owner(p_organization_id); if not exists(select 1 from public.journal_entries where id=p_journal_id and organization_id=p_organization_id and status='draft') then raise exception 'journal_not_editable'; end if; end; $$;
create or replace function public.create_journal_draft(p_organization_id uuid,p_journal_date date,p_reference text,p_description text,p_lines jsonb,p_branch_id uuid default null) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare v_id uuid:=gen_random_uuid(); v_line jsonb; v_n int:=0; begin perform public.assert_accounting_owner(p_organization_id); if p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and organization_id=p_organization_id) then raise exception 'invalid_branch'; end if; insert into public.journal_entries(id,organization_id,branch_id,journal_date,source_type,reference,description,created_by) values(v_id,p_organization_id,p_branch_id,p_journal_date,'manual_journal',nullif(trim(p_reference),''),trim(p_description),(select auth.uid())); for v_line in select * from jsonb_array_elements(p_lines) loop v_n:=v_n+1; insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount) values(p_organization_id,v_id,v_n,(v_line->>'account_id')::uuid,nullif(v_line->>'description',''),coalesce((v_line->>'debit')::numeric,0),coalesce((v_line->>'credit')::numeric,0)); end loop; perform public.accounting_audit(p_organization_id,'journal.created','journal_entry',v_id); return v_id; end; $$;
create or replace function public.post_journal_entry(p_organization_id uuid,p_journal_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$ declare j public.journal_entries%rowtype; v_debit numeric; v_credit numeric; v_number bigint; v_prefix text; v_padding smallint; v_suffix text; begin perform public.assert_accounting_owner(p_organization_id); select * into j from public.journal_entries where id=p_journal_id and organization_id=p_organization_id for update; if not found then raise exception 'not_found'; end if; if j.status='posted' then return jsonb_build_object('journal_id',j.id,'already_posted',true,'journal_number',j.journal_number); end if; if j.status<>'draft' then raise exception 'journal_not_postable'; end if; select * into v_debit,v_credit from (select coalesce(sum(debit_amount),0),coalesce(sum(credit_amount),0) from public.journal_lines where journal_entry_id=j.id) x; if v_debit<=0 or v_debit<>v_credit or (select count(*) from public.journal_lines where journal_entry_id=j.id)<2 then raise exception 'journal_not_balanced'; end if; select fy.id into j.financial_year_id from public.financial_years fy where fy.organization_id=p_organization_id and j.journal_date between fy.start_date and fy.end_date and fy.status='open'; if j.financial_year_id is null then raise exception 'financial_year_closed_or_missing'; end if; if exists(select 1 from public.journal_lines l left join public.accounts a on a.id=l.account_id and a.organization_id=p_organization_id where l.journal_entry_id=j.id and (a.id is null or not a.is_active or not a.allow_manual_posting)) then raise exception 'invalid_posting_account'; end if; select prefix,padding,suffix,next_number into v_prefix,v_padding,v_suffix,v_number from public.document_sequences where organization_id=p_organization_id and document_type='journal' and branch_id is null and financial_year_id is null for update; if v_number is null then raise exception 'journal_sequence_missing'; end if; update public.document_sequences set next_number=next_number+1 where organization_id=p_organization_id and document_type='journal' and branch_id is null and financial_year_id is null; update public.journal_entries set financial_year_id=j.financial_year_id,journal_number=v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,''),status='posted',posted_at=now(),posted_by=(select auth.uid()) where id=j.id; perform public.accounting_audit(p_organization_id,'journal.posted','journal_entry',j.id); return jsonb_build_object('journal_id',j.id,'already_posted',false,'journal_number',v_prefix||lpad(v_number::text,v_padding,'0')||coalesce(v_suffix,'')); end; $$;
create or replace function public.reverse_journal_entry(p_organization_id uuid,p_journal_id uuid,p_reversal_date date default current_date) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare j public.journal_entries%rowtype; v_id uuid:=gen_random_uuid(); begin perform public.assert_accounting_owner(p_organization_id); select * into j from public.journal_entries where id=p_journal_id and organization_id=p_organization_id for update; if j.status<>'posted' or j.reversed_by_journal_id is not null then raise exception 'journal_already_reversed_or_not_posted'; end if; insert into public.journal_entries(id,organization_id,branch_id,journal_date,source_type,source_id,reference,description,status,reversal_of_journal_id,created_by) values(v_id,p_organization_id,j.branch_id,p_reversal_date,j.source_type,null,'REV-'||coalesce(j.reference,''),'Reversal of '||j.journal_number,'draft',j.id,(select auth.uid())); insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount) select organization_id,v_id,line_number,account_id,description,credit_amount,debit_amount from public.journal_lines where journal_entry_id=j.id; perform public.post_journal_entry(p_organization_id,v_id); update public.journal_entries set status='reversed',reversed_by_journal_id=v_id where id=j.id; perform public.accounting_audit(p_organization_id,'journal.reversed','journal_entry',j.id); return v_id; end; $$;
create or replace function public.post_opening_balance_batch(p_organization_id uuid,p_batch_id uuid) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$ declare b public.opening_balance_batches%rowtype; v_id uuid:=gen_random_uuid(); begin perform public.assert_accounting_owner(p_organization_id); select * into b from public.opening_balance_batches where id=p_batch_id and organization_id=p_organization_id for update; if b.posted_journal_id is not null then return b.posted_journal_id; end if; if (select coalesce(sum(debit_amount),0) from public.opening_balance_lines where batch_id=b.id)<>(select coalesce(sum(credit_amount),0) from public.opening_balance_lines where batch_id=b.id) then raise exception 'opening_balance_not_balanced'; end if; insert into public.journal_entries(id,organization_id,financial_year_id,journal_date,source_type,source_id,description,created_by) values(v_id,p_organization_id,b.financial_year_id,b.opening_date,'opening_balance',b.id,coalesce(b.notes,'Opening balance'),(select auth.uid())); insert into public.journal_lines(organization_id,journal_entry_id,line_number,account_id,description,debit_amount,credit_amount) select p_organization_id,v_id,row_number() over(),account_id,description,debit_amount,credit_amount from public.opening_balance_lines where batch_id=b.id; perform public.post_journal_entry(p_organization_id,v_id); update public.opening_balance_batches set posted_journal_id=v_id,status='ready' where id=b.id; perform public.accounting_audit(p_organization_id,'opening_balance.posted','opening_balance_batch',b.id); return v_id; end; $$;
alter table public.journal_entries enable row level security; alter table public.journal_lines enable row level security; create policy journal_entries_member_select on public.journal_entries for select to authenticated using(public.is_active_org_member(organization_id)); create policy journal_lines_member_select on public.journal_lines for select to authenticated using(public.is_active_org_member(organization_id));
revoke all on public.journal_entries,public.journal_lines from anon; grant select on public.journal_entries,public.journal_lines to authenticated;
revoke all on function public.assert_journal_draft(uuid,uuid),public.create_journal_draft(uuid,date,text,text,jsonb,uuid),public.post_journal_entry(uuid,uuid),public.reverse_journal_entry(uuid,uuid,date),public.post_opening_balance_batch(uuid,uuid) from public,anon;
grant execute on function public.create_journal_draft(uuid,date,text,text,jsonb,uuid),public.post_journal_entry(uuid,uuid),public.reverse_journal_entry(uuid,uuid,date),public.post_opening_balance_batch(uuid,uuid) to authenticated;
